changeSet.sql:
CREATE OR ALTER TRIGGER [dbo].[Field_AfterUpsert] ON [dbo].[Field] FOR INSERT, UPDATE AS SET NOCOUNT ON;
-- formatted value logic only needs to run in cases where value is not null if exists( select 1 from inserted where [value] is not null or [formattedvalue] is not null) begin
UPDATE T SET T.FormattedValue = utility.GetFormattedFieldLookupValueWithMultiple(FT.Type, FT.LookupDisplayFormat, FT.LookupObjectType, FT.LookupObjectID, F.Value, FT.AllowMultipleValues) FROM Field T inner join inserted F on F.FieldTypeID = T.FieldTypeID and F.[Value] is not null and ((F.AssetID IS NOT NULL AND F.AssetID = T.AssetID) OR (F.IntersectID IS NOT NULL AND F.IntersectID = T.IntersectID) OR (F.IssueID IS NOT NULL AND F.IssueID = T.IssueID)) INNER JOIN FieldType FT ON FT.ID = T.FieldTypeID;
drop table if exists #insertedFields; create table #insertedFields (ObjectType varchar(250), ObjectID int); create clustered index IX_TempInsertedFields ON #insertedFields (ObjectType, ObjectID);
insert into #insertedFields select distinct replace(FT.[Object],'Type',''), FT.ObjectID from inserted i inner join FieldType FT on FT.ID = i.FieldTypeID where exists (select 1 from deleted d where d.id = i.id);
if exists( select 1 from Field TF inner join FieldType FT on FT.ID = TF.FieldTypeID inner join #insertedFields SF on FT.LookupObjectType = SF.ObjectType and FT.LookupObjectID = SF.ObjectID where TF.[Value] is not null) begin
UPDATE TF SET TF.FormattedValue = utility.GetFormattedFieldLookupValueWithMultiple(FT.Type, FT.LookupDisplayFormat, FT.LookupObjectType, FT.LookupObjectID, TF.Value, FT.AllowMultipleValues) from Field TF inner join FieldType FT on FT.ID = TF.FieldTypeID inner join #insertedFields SF on FT.LookupObjectType = SF.ObjectType and FT.LookupObjectID = SF.ObjectID where TF.[Value] is not null; end end
-- only update the assetid field if one was not already provided if exists( select 1 from inserted where AssetID is null ) begin UPDATE T SET T.AssetID = A.ID FROM Field T inner join inserted F on F.FieldTypeID = T.FieldTypeID and F.ObjectType = T.ObjectType and F.ObjectID = T.ObjectID and T.AssetID is null inner join Asset A on A.Object = F.ObjectType and A.ObjectID = F.ObjectID; end
-------------------------------------------- -- audit field value changes -------------------------------------------- Declare @ActionName varchar(20) = 'Add'; IF EXISTS(SELECT * FROM DELETED) BEGIN -- this is an update statement set @ActionName = 'Update'; END
INSERT INTO [queue].[Task] ([Action], [Object], [ObjectID], [Custom], AssetID) select distinct @ActionName, a.Object, coalesce(i.AssetID,0), ( select @ActionName as Action, a.Object as ActionObject, a.ObjectID as ActionObjectID, coalesce(i2.UpdatedBy, 0) as ResourceID, ( select f.FieldTypeID, ft.FriendlyName as [Name], f.FormattedValue as [Value] from field f inner join fieldtype ft on f.fieldtypeid = ft.id where f.objectid = i.objectid and f.objecttype = i.objecttype for json path ) as Fields from inserted i2 where i2.AssetID = i.AssetID group by AssetID, UpdatedBy for json path, WITHOUT_ARRAY_WRAPPER ) as [Custom], coalesce(i.AssetID,0) as [AssetID] from inserted i inner join asset a on a.ID = i.AssetID where i.[ObjectType] != 'Intersect' and i.[ObjectType] != 'Group';
-- handle relationships both sides need audit entries if exists(select 1 from inserted i where i.[IntersectID] is not null) begin -- object side of relationship INSERT INTO [queue].[Task] ([Action], [Object], [ObjectID], [Custom], AssetID) select distinct @ActionName, 'Intersect', inter.ID, ( select @ActionName as Action, a.Object as ActionObject, a.ObjectID as ActionObjectID, coalesce(i2.UpdatedBy, 0) as ResourceID, ( select f.FieldTypeID, ft.FriendlyName as [Name], f.FormattedValue as [Value] from field f inner join fieldtype ft on f.fieldtypeid = ft.id where f.objectid = i.objectid and f.objecttype = i.objecttype for json path ) as Fields from inserted i2 where i2.IntersectID = i.IntersectID group by ObjectType, ObjectID, UpdatedBy for json path, WITHOUT_ARRAY_WRAPPER ) as [Custom], coalesce(a.ID,0) as [AssetID] from inserted i inner join [intersect] inter on(i.IntersectID = inter.ID) inner join asset a on(a.ID = inter.ObjectAssetID) where i.[IntersectID] is not null;
-- subject side INSERT INTO [queue].[Task] ([Action], [Object], [ObjectID], [Custom], AssetID) select distinct @ActionName, 'Intersect', inter.ID, ( select @ActionName as Action, a.Object as ActionObject, a.ObjectID as ActionObjectID, coalesce(i2.UpdatedBy, 0) as ResourceID, ( select f.FieldTypeID, ft.FriendlyName as [Name], f.FormattedValue as [Value] from field f inner join fieldtype ft on f.fieldtypeid = ft.id where f.objectid = i.objectid and f.objecttype = i.objecttype for json path ) as Fields from inserted i2 where i2.ObjectID = i.ObjectID and i2.ObjectType = i.ObjectType group by ObjectType, ObjectID, UpdatedBy for json path, WITHOUT_ARRAY_WRAPPER ) as [Custom], coalesce(a.ID,0) as [AssetID] from inserted i inner join [intersect] inter on(i.IntersectID = inter.ID) inner join asset a on(a.ID = inter.SubjectAssetID) where i.[IntersectID] is not null; end

changeSet.rollback:
