-- only update the assetid field if one was not already provided if exists( select 1 from inserted where AssetID is null ) begin UPDATE T SET T.AssetID = A.ID FROM Field T inner join inserted F on F.FieldTypeID = T.FieldTypeID and F.ObjectType = T.ObjectType and F.ObjectID = T.ObjectID and T.AssetID is null inner join Asset A on A.Object = F.ObjectType and A.ObjectID = F.ObjectID; end
-------------------------------------------- -- audit field value changes -------------------------------------------- Declare @ActionName varchar(20) = 'Add'; IF EXISTS(SELECT * FROM DELETED) BEGIN -- this is an update statement set @ActionName = 'Update'; END
INSERT INTO [queue].[Task] ([Action], [Object], [ObjectID], [Custom], AssetID) select distinct @ActionName, i.ObjectType, i.ObjectID, ( select @ActionName as Action, i2.ObjectType as ActionObject, i2.ObjectID as ActionObjectID, coalesce(i2.UpdatedBy, 0) as ResourceID, ( select f.FieldTypeID, ft.FriendlyName as [Name], f.FormattedValue as [Value] from field f inner join fieldtype ft on f.fieldtypeid = ft.id where f.objectid = i.objectid and f.objecttype = i.objecttype for json path ) as Fields from inserted i2 where i2.ObjectID = i.ObjectID and i2.ObjectType = i.ObjectType group by ObjectType, ObjectID, UpdatedBy for json path, WITHOUT_ARRAY_WRAPPER ) as [Custom], coalesce(i.AssetID,0) as [AssetID] from inserted i where i.[ObjectType] != 'Intersect' and i.[ObjectType] != 'Group';
-- handle relationships both sides need audit entries if exists(select 1 from inserted where [objecttype]= 'Intersect') begin -- object side of relationship INSERT INTO [queue].[Task] ([Action], [Object], [ObjectID], [Custom], AssetID) select distinct @ActionName, i.ObjectType, i.ObjectID, ( select @ActionName as Action, a.Object as ActionObject, a.ObjectID as ActionObjectID, coalesce(i2.UpdatedBy, 0) as ResourceID, ( select f.FieldTypeID, ft.FriendlyName as [Name], f.FormattedValue as [Value] from field f inner join fieldtype ft on f.fieldtypeid = ft.id where f.objectid = i.objectid and f.objecttype = i.objecttype for json path ) as Fields from inserted i2 where i2.ObjectID = i.ObjectID and i2.ObjectType = i.ObjectType group by ObjectType, ObjectID, UpdatedBy for json path, WITHOUT_ARRAY_WRAPPER ) as [Custom], coalesce(a.ID,0) as [AssetID] from inserted i inner join [intersect] inter on(i.ObjectID = inter.ID and i.[ObjectType] = 'Intersect') inner join asset a on(a.ObjectID = inter.ObjectID and a.[Object] = inter.[Object]) where i.[ObjectType] = 'Intersect';
-- subject side INSERT INTO [queue].[Task] ([Action], [Object], [ObjectID], [Custom], AssetID) select distinct @ActionName, i.ObjectType, i.ObjectID, ( select @ActionName as Action, a.Object as ActionObject, a.ObjectID as ActionObjectID, coalesce(i2.UpdatedBy, 0) as ResourceID, ( select f.FieldTypeID, ft.FriendlyName as [Name], f.FormattedValue as [Value] from field f inner join fieldtype ft on f.fieldtypeid = ft.id where f.objectid = i.objectid and f.objecttype = i.objecttype for json path ) as Fields from inserted i2 where i2.ObjectID = i.ObjectID and i2.ObjectType = i.ObjectType group by ObjectType, ObjectID, UpdatedBy for json path, WITHOUT_ARRAY_WRAPPER ) as [Custom], coalesce(a.ID,0) as [AssetID] from inserted i inner join [intersect] inter on(i.ObjectID = inter.ID and i.[ObjectType] = 'Intersect') inner join asset a on(a.ObjectID = inter.SubjectID and a.[Object] = inter.[Subject]) where i.[ObjectType] = 'Intersect'; end

changeSet.sql:
CREATE OR ALTER TRIGGER [dbo].[Field_AfterDelete] ON [dbo].[Field] AFTER DELETE AS BEGIN -- SET NOCOUNT ON added to prevent extra result sets from -- interfering with SELECT statements. SET NOCOUNT ON;
drop table if exists #tempdeleted; drop table if exists #tempdeletedUQ; drop table if exists #tempdeletedUQFields;
select fieldtypeid, AssetID, IntersectID, IssueID, UpdatedBy into #tempdeleted from deleted;
create index idx_tempdeleted on #tempdeleted(fieldtypeid) INCLUDE([AssetID],[IntersectID],[IssueID]);
select distinct AssetID, IntersectID, IssueID into #tempdeletedUQ from #tempdeleted;
select distinct fieldtypeid, AssetID, IntersectID, IssueID, UpdatedBy into #tempdeletedUQFields from #tempdeleted;
create index idx_tempdeletedUQFields on #tempdeletedUQFields(fieldtypeid) INCLUDE([AssetID],[IntersectID],[IssueID]);;
declare @resourceId int = null
if (select count(distinct updatedby) from #tempdeletedUQFields) > 1 begin set @resourceid = 0 end
-- audit field delete Asset INSERT INTO [queue].[Task] ([Action], [Object], [ObjectID], [Custom], AssetID) select 'Delete', A.Object, A.ObjectID, (select 'Delete' as Action, A.Object as ActionObject, A.ObjectID as ActionObjectID, coalesce(@resourceId, i2.UpdatedBy, 0) as ResourceID, ( select (select d3.FieldTypeID, coalesce(ft.FriendlyName, '<deleted field type>') as [Name], '' as [Value] from #tempdeleted d3 left join fieldtype ft on d3.fieldtypeid = ft.id where d3.AssetID = d.AssetID for xml path('Field'), TYPE ) for xml path('FieldInfo'), TYPE ) from #tempdeletedUQFields i2 where i2.AssetID = d.AssetID group by AssetID, coalesce(@resourceId, i2.UpdatedBy, 0) for xml path('fields')) , coalesce(d.AssetID,0) as [AssetID] from #tempdeletedUQ d inner join asset A on d.AssetID=A.ID;
-- audit field delete intersect INSERT INTO [queue].[Task] ([Action], [Object], [ObjectID], [Custom], AssetID) select 'Delete', 'Intersect', I.ID, (select 'Delete' as Action, 'Intersect', I.ID, coalesce(@resourceId, i2.UpdatedBy, 0) as ResourceID, ( select (select d3.FieldTypeID, coalesce(ft.FriendlyName, '<deleted field type>') as [Name], '' as [Value] from #tempdeleted d3 left join fieldtype ft on d3.fieldtypeid = ft.id where d3.intersectID = d.intersectID for xml path('Field'), TYPE ) for xml path('FieldInfo'), TYPE ) from #tempdeletedUQFields i2 where i2.intersectID = d.intersectID group by intersectID, coalesce(@resourceId, i2.UpdatedBy, 0) for xml path('fields')) , coalesce(d.AssetID,0) as [AssetID] from #tempdeletedUQ d inner join [Intersect] I on d.IntersectID=I.ID;
-- audit field delete issue INSERT INTO [queue].[Task] ([Action], [Object], [ObjectID], [Custom], AssetID) select 'Delete', 'Issue', I.ID, (select 'Delete' as Action, 'Issue', I.ID, coalesce(@resourceId, i2.UpdatedBy, 0) as ResourceID, ( select (select d3.FieldTypeID, coalesce(ft.FriendlyName, '<deleted field type>') as [Name], '' as [Value] from #tempdeleted d3 left join fieldtype ft on d3.fieldtypeid = ft.id where d3.IssueID = d.IssueID for xml path('Field'), TYPE ) for xml path('FieldInfo'), TYPE ) from #tempdeletedUQFields i2 where i2.IssueID = d.IssueID group by IssueID, coalesce(@resourceId, i2.UpdatedBy, 0) for xml path('fields')) , coalesce(d.AssetID,0) as [AssetID] from #tempdeletedUQ d inner join issue I on d.IssueID=I.ID; END
